//! 📣️ Real scoped view aliases retain window routing independently of the action which first showed them.
use super::*;
use semio_framework_job::OriginalConstructionAdmission;
use semio_framework_value::{ValueError,ValueRefusalKind,RetainedCloneStep,RetainedWorkOutcome,retained_clone::RetainedCloneClose};
use std::mem::ManuallyDrop;
const WINDOWS:usize=semio_framework::VIEW_CONTEXT_WINDOW_INSTANCES;
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"host event routing changed its original view or window")}
fn window(meta:&ActionMeta)->Option<&str>{meta.view_state.as_deref()?.window_id.as_deref()}
/// 🪜️ A paid one-unit state change settles through the resident admission and its resident marker, so a pending turn never repeats the change.
fn paid(cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,marker:&mut Option<()>,bytes:usize,run:impl FnOnce())->Result<bool,OriginalTurnFailure>{let settled=semio_framework_job::admit_original_construction_settled(cx,admission,marker,OriginalConstructionDemand{items:1,copy_bytes:bytes,capacity_bytes:0,release_bytes:0,depth:1},1,|_,_|{run();RetainedWorkOutcome{result:Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})),work:1}})?;if settled{marker.take();}Ok(settled)}
/// 🪟️ Every occupied slot owns a paid alias of one actual addressed view, never a reconstructed window context.
pub struct OriginalHostEventRoutes{slots:ManuallyDrop<[Option<ActionMeta>;WINDOWS]>,stamp:[u64;WINDOWS],next:u64,upper:usize,source:Option<(usize,u32)>,phase:u8,index:usize,roster:usize,byte:usize,empty:Option<usize>,selected:Option<usize>,retirement:RetainedCloneClose,construction:OriginalConstructionAdmission,unit:Option<()>,replacement:ManuallyDrop<Option<ActionMeta>>,turn:bool,pub pending_base:bool,pub delivering:bool,pub cursor:usize,pub completed:bool,live_cursor:usize,live_byte:usize,live:Option<bool>,lookup:usize,lookup_byte:usize,lookup_match:Option<usize>,pub delivered_epoch:u64,pub epoch:u64,pub metadata:ManuallyDrop<Option<ActionMeta>>,pub event:ManuallyDrop<Option<crate::HostEvent>>,pub outcome:ManuallyDrop<Option<semio_framework::kernel::InvocationResult>>}
impl Default for OriginalHostEventRoutes{fn default()->Self{Self{slots:ManuallyDrop::new(std::array::from_fn(|_|None)),stamp:[0;WINDOWS],next:0,upper:0,source:None,phase:0,index:0,roster:0,byte:0,empty:None,selected:None,retirement:Default::default(),construction:Default::default(),unit:None,replacement:ManuallyDrop::new(None),turn:false,pending_base:false,delivering:false,cursor:0,completed:false,live_cursor:0,live_byte:0,live:None,lookup:0,lookup_byte:0,lookup_match:None,delivered_epoch:0,epoch:0,metadata:ManuallyDrop::new(None),event:ManuallyDrop::new(None),outcome:ManuallyDrop::new(None)}}}
impl OriginalHostEventRoutes{
 /// 📥️ Remote base movement enqueues only an allocation-free marker; fanout is performed by funded background turns.
 pub fn base_moved(&mut self){self.epoch=self.epoch.wrapping_add(1);self.pending_base=true;}
 pub fn pending(&self)->bool{self.pending_base||self.delivering||self.metadata.is_some()||self.event.is_some()||self.outcome.is_some()}
 pub fn runnable(&self,active_action:bool)->bool{self.pending()&&(self.delivering||!active_action)}
 pub fn take_turn(&mut self)->bool{self.turn=!self.turn;self.turn}
 pub fn cache_busy(&self)->bool{self.source.is_some()&&self.phase!=5}
 pub fn capture_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.replacement.is_some(){let index=self.selected.ok_or_else(invalid)?;if self.slots[index].is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}return Ok(RetirementDemand{copy_bytes:2*size_of::<Option<ActionMeta>>()+size_of::<(u64,u8,usize)>(),depth:1,..Default::default()})}Ok(RetirementDemand{copy_bytes:size_of::<u8>(),depth:1,..Default::default()})}
 pub fn settle_capture(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.replacement.is_some(){self.finish_capture(cx)?;return Ok(false)}if !self.retirement.is_empty(){cx.with_original_retirement(|cx|self.close_retirement(cx))?;return Ok(false)}if self.cache_busy(){let d=RetirementDemand{copy_bytes:size_of::<u8>(),depth:1,..Default::default()};semio_framework_job::close_original_retained_step(cx,d,|_|{self.phase=5;RetainedWorkOutcome::<RetainedCloneStep,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;return Ok(false)}Ok(true)}
 pub fn start(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.delivering{return Ok(true)}paid(cx,&mut self.construction,&mut self.unit,size_of::<(bool,bool,usize,u64)>(),||{self.delivering=true;self.pending_base=false;self.cursor=0;self.delivered_epoch=self.epoch;self.live_cursor=0;self.live_byte=0;self.live=None;})?;Ok(false)}
 pub fn next_window(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{paid(cx,&mut self.construction,&mut self.unit,size_of::<(usize,usize,usize,Option<bool>,bool)>(),||{self.cursor+=1;self.live_cursor=0;self.live_byte=0;self.live=None;self.completed=false;})?;Ok(())}
 pub fn complete_current(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{paid(cx,&mut self.construction,&mut self.unit,size_of::<bool>(),||self.completed=true)?;Ok(())}
 pub fn finish_cancelled(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=RetirementDemand{copy_bytes:size_of::<(bool,bool,u64)>(),depth:1,..Default::default()};cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|_|{self.delivering=false;self.pending_base=false;self.delivered_epoch=self.epoch;RetainedWorkOutcome::<RetainedCloneStep,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(())})}
 pub fn finish(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{paid(cx,&mut self.construction,&mut self.unit,size_of::<(bool,bool)>(),||{self.delivering=false;self.pending_base=self.epoch!=self.delivered_epoch;})?;Ok(())}
 /// 🔎️ A cached exact window remains addressable only while the latest actual roster still carries its identity.
 pub fn advance_liveness(&mut self,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{if let Some(value)=self.live{return Ok(Some(value))}let Some(target)=self.route(self.cursor).and_then(window)else{paid(cx,&mut self.construction,&mut self.unit,size_of::<Option<bool>>(),||self.live=Some(false))?;return Ok(None)};let Some(view)=self.latest().and_then(|meta|meta.view_state.as_deref())else{paid(cx,&mut self.construction,&mut self.unit,size_of::<Option<bool>>(),||self.live=Some(false))?;return Ok(None)};let Some(candidate)=view.window_instances.get(self.live_cursor)else{paid(cx,&mut self.construction,&mut self.unit,size_of::<Option<bool>>(),||self.live=Some(false))?;return Ok(None)};let count=if target.len()==candidate.id.len(){64.min(target.len().saturating_sub(self.live_byte))}else{0};let same=target.len()==candidate.id.len()&&target.as_bytes()[self.live_byte..self.live_byte+count]==candidate.id.as_bytes()[self.live_byte..self.live_byte+count];let target_len=target.len();paid(cx,&mut self.construction,&mut self.unit,count*2+size_of::<(usize,usize,Option<bool>)>(),||{if same{self.live_byte+=count;if self.live_byte==target_len{self.live=Some(true)}}else{self.live_cursor+=1;self.live_byte=0;}})?;Ok(None)}
 pub fn prepare_metadata(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.metadata.is_some(){return Ok(true)}let meta=self.slots.get(self.cursor).and_then(Option::as_ref).ok_or_else(invalid)?;meta.admit_routing_alias(&mut self.construction,&mut self.metadata,cx)}
 pub fn prepare_event(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.event.is_some(){return Ok(true)}let target=self.metadata.as_ref().and_then(window).ok_or_else(invalid)?;let d=RetirementDemand{copy_bytes:2*size_of::<crate::HostEvent>()+target.len(),capacity_bytes:target.len(),depth:1,..Default::default()};semio_framework_job::admit_original_construction_settled(cx,&mut self.construction,&mut self.event,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},1,|_,_|RetainedWorkOutcome{result:Ok((crate::HostEvent::BaseMoved{window_id:target.to_owned()},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})),work:1})}
 pub fn delivery_is_empty(&self)->bool{self.metadata.is_none()&&self.event.is_none()&&self.outcome.is_none()&&self.retirement.is_empty()}
 pub fn delivery_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.outcome.is_some(){return self.retirement.next_owner_demands::<semio_framework::kernel::InvocationResult>(true,&None,body)}if self.event.is_some(){return self.retirement.next_owner_demands::<crate::HostEvent>(true,&None,body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}Ok(Default::default())}
 pub fn prepare_window_alias(&mut self,target:&str,output:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{if output.is_some(){return Ok(Some(true))}if let Some(index)=self.lookup_match{let meta=self.slots[index].as_ref().ok_or_else(invalid)?;return meta.admit_routing_alias(&mut self.construction,output,cx).map(|done|done.then_some(true))}if self.lookup==self.upper{return Ok(Some(false))}let candidate=self.slots[self.lookup].as_ref().and_then(window);let count=candidate.map_or(0,|candidate|if candidate.len()==target.len(){64.min(target.len().saturating_sub(self.lookup_byte))}else{0});let same=candidate.is_some_and(|candidate|candidate.len()==target.len()&&candidate.as_bytes()[self.lookup_byte..self.lookup_byte+count]==target.as_bytes()[self.lookup_byte..self.lookup_byte+count]);paid(cx,&mut self.construction,&mut self.unit,count*2+size_of::<(usize,usize,Option<usize>)>(),||{if same{self.lookup_byte+=count;if self.lookup_byte==target.len(){self.lookup_match=Some(self.lookup)}}else{self.lookup+=1;self.lookup_byte=0;}})?;Ok(None)}
 pub fn reset_lookup(&mut self,completed:&mut bool,removed:&mut bool,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{paid(cx,&mut self.construction,&mut self.unit,size_of::<(usize,usize,Option<usize>,bool,bool)>(),||{self.lookup=0;self.lookup_byte=0;self.lookup_match=None;*completed=false;*removed=false;})?;Ok(())}
 pub fn close_delivery(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.with_original_retirement(|cx|{if !self.retirement.is_empty(){self.close_retirement(cx)?;return Ok(false)}let body=cx.retained_grant().maximum_copy_bytes;macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,body)?;semio_framework_job::close_original_effect_step(cx,d,|effect|{let turn=self.retirement.begin_granted(&mut self.$field,effect);semio_framework_value::RetainedWorkPoll::Complete(RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default())))})})?;return Ok(false)}}}close!(outcome,semio_framework::kernel::InvocationResult);close!(event,crate::HostEvent);close!(metadata,ActionMeta);Ok(true)})}
 pub fn route(&self,index:usize)->Option<&ActionMeta>{self.slots.get(index)?.as_ref()}
 pub fn extent(&self)->usize{self.upper}
 pub fn latest(&self)->Option<&ActionMeta>{(0..self.upper).filter(|index|self.slots[*index].is_some()).max_by_key(|index|self.stamp[*index]).and_then(|index|self.slots[index].as_ref())}
 /// 🧷️ Each comparison reads at most sixty-four bytes before the same original caller yields.
 pub fn capture(&mut self,meta:&ActionMeta,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  let Some(view)=meta.view_state.as_ref()else{return Ok(true)};let Some(target)=view.window_id.as_deref()else{return Ok(true)};if self.delivering{return Ok(false)}let identity=(Arc::as_ptr(view)as usize,meta.instance_id);
  if self.source!=Some(identity){if self.cache_busy(){if self.replacement.is_some(){self.finish_capture(cx)?;}else{paid(cx,&mut self.construction,&mut self.unit,size_of::<u8>(),||self.phase=5)?;}return Ok(false)}if paid(cx,&mut self.construction,&mut self.unit,size_of::<(usize,u32,u8,usize,Option<usize>)>(),||{self.source=Some(identity);self.phase=1;self.index=0;self.byte=0;self.empty=None;self.selected=None;})?{return Ok(false)}return Ok(false)}
  if self.phase==5{return Ok(true)}
  match self.phase{
   1=>{if self.index==self.upper{if let Some(index)=self.empty.or_else(||(self.upper<WINDOWS).then_some(self.upper)){paid(cx,&mut self.construction,&mut self.unit,size_of::<Option<usize>>()+size_of::<u8>(),||{self.selected=Some(index);self.phase=4;})?;}else{paid(cx,&mut self.construction,&mut self.unit,3*size_of::<usize>()+size_of::<u8>(),||{self.index=0;self.roster=0;self.byte=0;self.phase=2;})?;}return Ok(false)}let old=self.slots[self.index].as_ref().and_then(window);let count=old.map_or(0,|old|if old.len()==target.len(){64.min(target.len().saturating_sub(self.byte))}else{0});let same=old.is_some_and(|old|old.len()==target.len()&&old.as_bytes()[self.byte..self.byte+count]==target.as_bytes()[self.byte..self.byte+count]);if paid(cx,&mut self.construction,&mut self.unit,count*2+3*size_of::<usize>()+size_of::<u8>(),||{if self.slots[self.index].is_none()&&self.empty.is_none(){self.empty=Some(self.index)}if same{self.byte+=count;if self.byte==target.len(){self.selected=Some(self.index);self.phase=4}}else{self.index+=1;self.byte=0;}})?{}},
   2=>{if self.index==WINDOWS{return Err(invalid().into())}let old=self.slots[self.index].as_ref().and_then(window).ok_or_else(invalid)?;if self.roster==view.window_instances.len(){paid(cx,&mut self.construction,&mut self.unit,size_of::<Option<usize>>()+size_of::<u8>(),||{self.selected=Some(self.index);self.phase=4;})?;return Ok(false)}let candidate=&view.window_instances[self.roster].id;let count=if candidate.len()==old.len(){64.min(old.len().saturating_sub(self.byte))}else{0};let same=candidate.len()==old.len()&&candidate.as_bytes()[self.byte..self.byte+count]==old.as_bytes()[self.byte..self.byte+count];paid(cx,&mut self.construction,&mut self.unit,count*2+3*size_of::<usize>(),||{if same{self.byte+=count;if self.byte==old.len(){self.index+=1;self.roster=0;self.byte=0}}else{self.roster+=1;self.byte=0;}})?;},
   3|6=>{self.finish_capture(cx)?;},
   4=>{if meta.admit_routing_alias(&mut self.construction,&mut self.replacement,cx)?{self.phase=3;}},
   _=>return Err(invalid().into()),
  }Ok(self.phase==5)
 }
 pub fn close_retirement(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let body=cx.retained_grant().maximum_copy_bytes;let selected=self.retirement.select(body)?;let d=selected.demands();semio_framework_job::close_original_effect_step(cx,d,|effect|selected.step(effect))?;Ok(())}
 pub fn finish_capture(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let index=self.selected.ok_or_else(invalid)?;cx.with_original_retirement(|cx|{if !self.retirement.is_empty(){return self.close_retirement(cx)}if self.slots[index].is_some(){let d=self.retirement.next_owner_demands::<ActionMeta>(true,&None,cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_effect_step(cx,d,|effect|{let turn=self.retirement.begin_granted(&mut self.slots[index],effect);semio_framework_value::RetainedWorkPoll::Complete(RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default())))})})?;return Ok(())}let bytes=2*size_of::<Option<ActionMeta>>()+size_of::<(u64,u8,usize)>();semio_framework_job::close_original_retained_step(cx,RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()},|_|{self.slots[index]=self.replacement.take();self.next=self.next.wrapping_add(1);self.stamp[index]=self.next;self.upper=self.upper.max(index+1);self.phase=5;RetainedWorkOutcome::<RetainedCloneStep,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})),work:1}})?;Ok(())})}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.outcome.is_some(){return self.retirement.next_owner_demands::<semio_framework::kernel::InvocationResult>(true,&None,body)}if self.event.is_some(){return self.retirement.next_owner_demands::<crate::HostEvent>(true,&None,body)}if self.replacement.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}if self.slots.iter().any(Option::is_some){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}Ok(Default::default())}
 pub fn terminal_is_empty(&self)->bool{self.replacement.is_none()&&self.retirement.is_empty()&&self.outcome.is_none()&&self.event.is_none()&&self.metadata.is_none()&&self.slots.iter().all(Option::is_none)&&self.construction.terminal_is_empty()}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.retirement.is_empty(){self.close_retirement(cx)?;return Ok(false)}let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;macro_rules! close{($slot:expr)=>{if $slot.is_some(){semio_framework_job::close_original_effect_step(cx,d,|effect|{let turn=self.retirement.begin_granted($slot,effect);semio_framework_value::RetainedWorkPoll::Complete(RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default())))})})?;return Ok(false)}}}close!(&mut *self.outcome);close!(&mut *self.event);close!(&mut *self.metadata);close!(&mut *self.replacement);for index in 0..WINDOWS{close!(&mut self.slots[index]);}if self.construction.terminal_is_empty(){return Ok(true)}self.construction.close_step(cx)?;Ok(self.construction.terminal_is_empty())}
}
